('Accounts Payable Standard','2026-03-27 12:52:58.345285','2026-05-20 20:07:04.855362','Administrator','Administrator',0,0,'Report',NULL,'Accounts Payable','Accounts','en','Yes',1,0,'chrome','JS',0,'<style type=\"text/css\">\n    body, html {\n        margin-top: 10px;\n        padding: 0;\n        width: 100%;\n        height: auto;\n        font-family: Inter, sans-serif;\n        font-size: 14px;\n        line-height: 21px;\n        color: #171717;\n    }\n\n    .title-letter-spacing {\n        font-size: 14px;\n        font-weight: 600;\n        color: #171717;\n    }\n\n    .report-table table {\n        width: 100%;\n        table-layout: fixed;\n        border-collapse: separate;\n        border-spacing: 0;\n    }\n\n    .report-table thead th {\n        background: #f8f8f8;\n        text-align: center;\n        font-size: 14px;\n        font-weight: 420;\n        color: #7c7c7c;\n        border-top: 1px solid #ededed;\n        border-bottom: 1px solid #ededed;\n        padding: 6px 8px;\n    }\n\n    .report-table tbody td {\n        padding: 6px 8px;\n        border-bottom: 1px solid #ededed;\n        vertical-align: top;\n        word-wrap: break-word;\n        font-size: 14px;\n    }\n\n    .report-table thead tr:first-child th:first-child {\n        border-left: 1px solid #ededed;\n        border-top-left-radius: 10px;\n        border-bottom-left-radius: 10px;\n    }\n\n    .report-table thead tr:first-child th:last-child {\n        border-right: 1px solid #ededed;\n        border-top-right-radius: 10px;\n        border-bottom-right-radius: 10px;\n    }\n\n    .report-table tbody tr:last-child td {\n        border-bottom: none;\n    }\n\n    .text-center { text-align: center; }\n    .text-right { text-align: right; font-variant-numeric: tabular-nums; }\n    .text-left { text-align: left; }\n\n    .text-bold { font-weight: 700; }\n\n    .text-muted { color: #7c7c7c !important; }\n\n    .report-meta {\n        margin: 10px 0 14px;\n        padding: 8px 10px;\n        color: #171717;\n        font-size: 14px;\n        display: flex;\n        justify-content: space-between;\n        align-items: flex-start;\n        gap: 12px;\n    }\n\n    .report-meta .left,\n    .report-meta .right {\n        display: flex;\n        flex-direction: column;\n    }\n\n    .report-meta .filter-row {\n        margin-bottom: 4px;\n        line-height: 1.5;\n    }\n\n    .report-meta strong {\n        color: #7c7c7c;\n        font-weight: 500;\n    }\n\n    @media print {\n        @page {\n            size: A4;\n            margin-top: 10mm;\n        }\n\n        thead {\n            display: table-header-group;\n        }\n\n        tfoot {\n            display: table-footer-group;\n        }\n\n        tr {\n            page-break-inside: avoid;\n        }\n\n        .no-print {\n            display: none !important;\n        }\n    }\n</style>\n\n<br>\n\n<div>\n\n    <!-- Title -->\n    <div class=\"text-center\" style=\"margin-bottom: 12px;\">\n        <div class=\"title-letter-spacing\">\n            {%= __(report.report_name) %}\n        </div>\n    </div>\n\n    <!-- Meta -->\n    <div class=\"report-meta\">\n        <div class=\"left\">\n            <div>\n                <strong>{%= __(\"Supplier\") %}:</strong>\n                {%= (filters.party.length && filters.party.join(\", \")) || __(\"All Parties\") %}\n            </div>\n        </div>\n\n        <div class=\"right text-right\">\n            <div>\n                <strong>{%= __(\"Report Date\") %}:</strong>\n                {%= frappe.datetime.str_to_user(filters.report_date) %}\n            </div>\n        </div>\n    </div>\n\n    <!-- Main Table -->\n    <div class=\"report-table\">\n        <table>\n            <thead>\n                <tr>\n                    <th style=\"width: 8em; text-align: left;\">{%= __(\"Date\") %}</th>\n                    <th style=\"text-align: left;\">{%= __(\"Reference\") %}</th>\n\n                    {% if(filters.show_remarks) { %}\n                        <th style=\"text-align: left;\">{%= __(\"Remarks\") %}</th>\n                    {% } %}\n\n                    <th style=\"width: 10em; text-align: right;\">{%= __(\"Age (Days)\") %}</th>\n                    <th style=\"width: 10em; text-align: right;\">{%= __(\"Invoiced Amount\") %}</th>\n                    <th style=\"width: 11em; text-align: right;\">{%= __(\"Outstanding Amount\") %}</th>\n                </tr>\n            </thead>\n\n            <tbody>\n                {% for(var i=0, l=data.length; i<l; i++) { %}\n                    <tr>\n                        <td class=\"text-left\">{%= frappe.datetime.str_to_user(data[i][\"posting_date\"]) %}</td>\n\n                        <td class=\"{% if(i == data.length - 1) { %}text-left text-bold{% } %}\">\n                            {% if(i == data.length - 1) { %}\n                                {%= __(\"Total\") %}\n                            {% } else { %}\n                                {%= data[i][\"voucher_no\"] %}\n                            {% } %}\n                        </td>\n\n                        {% if(filters.show_remarks) { %}\n                            <td class=\"text-left\">\n                                {% if(data[i][\"remarks\"] && data[i][\"remarks\"] != \"No Remarks\") { %}\n                                    {%= data[i][\"remarks\"] %}\n                                {% } %}\n                            </td>\n                        {% } %}\n\n                        <td class=\"text-right\">{%= data[i][\"age\"] %}</td>\n                        <td class=\"text-right\">{%= format_currency(data[i][\"invoiced\"], data[i][\"currency\"]) %}</td>\n                        <td class=\"text-right\">{%= format_currency(data[i][\"outstanding\"], data[i][\"currency\"]) %}</td>\n                    </tr>\n                {% } %}\n            </tbody>\n        </table>\n    </div>\n\n    &nbsp;\n\n    {% if(filters.show_future_payments) { %}\n        {%\n            var balance_row = data.slice(-1).pop();\n            var start = report.columns.findIndex(e => e.fieldname == \'age\');\n            var currency = data[data.length - 1][\"currency\"];\n\n            var ranges = [\n                report.columns[start].label,\n                report.columns[start+1].label,\n                report.columns[start+2].label,\n                report.columns[start+3].label,\n                report.columns[start+4].label,\n                report.columns[start+5].label\n            ];\n        %}\n\n        {% if(balance_row) { %}\n        <div class=\"report-table\">\n            <table>\n                <thead>\n                    <tr>\n                        <th style=\"text-align: right;\"></th>\n                        {% for(var i = 0; i < ranges.length; i++) { %}\n                            <th style=\"text-align: right;\">{%= __(ranges[i]) %}</th>\n                        {% } %}\n                        <th style=\"text-align: right;\">{%= __(\"Total\") %}</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td>{%= __(\"Total Outstanding\") %}</td>\n                        <td class=\"text-right\">{%= format_number(balance_row[\"age\"], null, 2) %}</td>\n                        <td class=\"text-right\">{%= format_currency(balance_row[\"range1\"], currency) %}</td>\n                        <td class=\"text-right\">{%= format_currency(balance_row[\"range2\"], currency) %}</td>\n                        <td class=\"text-right\">{%= format_currency(balance_row[\"range3\"], currency) %}</td>\n                        <td class=\"text-right\">{%= format_currency(balance_row[\"range4\"], currency) %}</td>\n                        <td class=\"text-right\">{%= format_currency(balance_row[\"range5\"], currency) %}</td>\n                        <td class=\"text-right\">{%= format_currency(flt(balance_row[\"outstanding\"]), currency) %}</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        {% } %}\n    {% } %}\n\n    <p class=\"text-right text-muted\">\n        {%= __(\"Printed on {0}\", [\n            frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())\n        ]) %}\n    </p>\n\n</div>',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Accounts Payable Summary Standard','2026-03-29 01:59:18.659670','2026-05-20 20:10:28.243370','Administrator','Administrator',0,0,'Report',NULL,'Accounts Payable Summary','Accounts','en','Yes',1,0,'chrome','JS',0,'<style type=\"text/css\">\n    body, html {\n        margin-top: 10px;\n        padding: 0;\n        width: 100%;\n        height: auto;\n        font-family: Inter, sans-serif;\n        font-size: 14px;\n        line-height: 21px;\n        color: #171717;\n    }\n\n    .title-letter-spacing {\n        font-size: 14px;\n        font-weight: 600;\n        color: #171717;\n    }\n\n    .report-table table {\n        width: 100%;\n        table-layout: fixed;\n        border-collapse: separate;\n        border-spacing: 0;\n    }\n\n    .report-table thead th {\n        background: #f8f8f8;\n        font-size: 14px;\n        font-weight: 420;\n        color: #7c7c7c;\n        border-top: 1px solid #ededed;\n        border-bottom: 1px solid #ededed;\n        padding: 6px 8px;\n    }\n\n    .report-table tbody td {\n        padding: 6px 8px;\n        border-bottom: 1px solid #ededed;\n        vertical-align: top;\n        word-wrap: break-word;\n        font-size: 14px;\n    }\n\n    .report-table thead tr:first-child th:first-child {\n        border-left: 1px solid #ededed;\n        border-top-left-radius: 10px;\n        border-bottom-left-radius: 10px;\n    }\n\n    .report-table thead tr:first-child th:last-child {\n        border-right: 1px solid #ededed;\n        border-top-right-radius: 10px;\n        border-bottom-right-radius: 10px;\n    }\n\n    .report-table tbody tr:last-child td {\n        border-bottom: none;\n    }\n\n    .report-meta {\n        margin: 10px 0 14px;\n        padding: 8px 10px;\n        color: #171717;\n        font-size: 14px;\n        display: flex;\n        justify-content: space-between;\n        align-items: flex-start;\n        gap: 12px;\n    }\n\n    .report-meta .left,\n    .report-meta .right {\n        display: flex;\n        flex-direction: column;\n    }\n\n    .report-meta .filter-row {\n        margin-bottom: 4px;\n        line-height: 1.5;\n    }\n\n    .report-meta strong {\n        color: #7c7c7c;\n        font-weight: 500;\n    }\n\n    .text-center { text-align: center; }\n    .text-right { text-align: right; font-variant-numeric: tabular-nums; }\n    .text-left { text-align: left; }\n    .text-bold { font-weight: 700; }\n\n    .text-muted {\n        color: #7c7c7c !important;\n    }\n\n    @media print {\n        @page {\n            size: A4;\n            margin-top: 10mm;\n        }\n\n        thead {\n            display: table-header-group;\n        }\n\n        tfoot {\n            display: table-footer-group;\n        }\n\n        tr {\n            page-break-inside: avoid;\n        }\n    }\n</style>\n\n<br>\n\n<div>\n\n    <div class=\"text-center\" style=\"margin-bottom: 12px;\">\n        <div class=\"title-letter-spacing\">\n            {%= __(report.report_name) %}\n        </div>\n    </div>\n\n   <div class=\"report-meta\">\n        <div class=\"left\">\n            <div>\n                <strong>{%= __(\"Supplier\") %}:</strong>\n                {%= (filters.party && filters.party.length && filters.party.join(\", \")) || __(\"All Parties\") %}\n            </div>\n        </div>\n\n        <div class=\"right text-right\">\n             <div>\n                <strong>{%= __(\"Ageing Based On\") %}:</strong>\n                {%= __(filters.ageing_based_on) %}\n            </div>\n            <div>\n                <strong>{%= __(\"As on Date\") %}:</strong>\n                {%= frappe.datetime.str_to_user(filters.report_date) %}\n            </div>\n        </div>\n    </div>\n\n    <div class=\"report-table\">\n        <table>\n            <thead>\n                <tr>\n                    <th class=\"text-left\">{%= __(\"Supplier\") %}</th>\n                    <th class=\"text-right\">{%= __(\"Total Invoiced Amount\") %}</th>\n                    <th class=\"text-right\">{%= __(\"Total Paid Amount\") %}</th>\n                    <th class=\"text-right\">{%= __(\"Debit Note Amount\") %}</th>\n                    <th class=\"text-right\">{%= __(\"Total Outstanding Amount\") %}</th>\n                </tr>\n            </thead>\n\n            <tbody>\n                {% for (var i = 0, l = data.length; i < l; i++) { \n                    var row = data[i];\n                    if (!(row.party || row.is_total_row)) continue;\n                %}\n                    <tr>\n                        <td class=\"{% if (row.is_total_row) { %}text-bold{% } %}\">\n                            {% if (row.is_total_row) { %}\n                                {%= __(\"Total\") %}\n                            {% } else { %}\n                                {%= row.party %}\n                            {% } %}\n                        </td>\n\n                        <td class=\"text-right\">\n                            {%= format_currency(row.invoiced, row.currency) %}\n                        </td>\n                        <td class=\"text-right\">\n                            {%= format_currency(row.paid, row.currency) %}\n                        </td>\n                        <td class=\"text-right\">\n                            {%= format_currency(row.debit_note, row.currency) %}\n                        </td>\n                        <td class=\"text-right\">\n                            {%= format_currency(row.outstanding, row.currency) %}\n                        </td>\n                    </tr>\n                {% } %}\n            </tbody>\n        </table>\n    </div>\n\n    <p class=\"text-right text-muted\">\n        {%= __(\"Printed on {0}\", [\n            frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())\n        ]) %}\n    </p>\n\n</div>',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Accounts Receivable Standard','2026-03-26 21:59:39.241833','2026-05-20 20:04:55.230531','Administrator','Administrator',0,0,'Report',NULL,'Accounts Receivable','Accounts','en','Yes',1,0,'chrome','JS',0,'<style type=\"text/css\">\n    body, html {\n        margin-top: 10px;\n        padding: 0;\n        width: 100%;\n        height: auto;\n        font-family: Inter, sans-serif;\n        font-size: 14px;\n        line-height: 21px;\n        color: #171717;\n    }\n\n    .title-letter-spacing {\n        font-size: 14px;\n        font-weight: 600;\n        color: #171717;\n    }\n\n    .report-table table {\n        width: 100%;\n        table-layout: fixed;\n        border-collapse: separate;\n        border-spacing: 0;\n    }\n\n    .report-table thead th {\n        background: #f8f8f8;\n        text-align: center;\n        font-size: 14px;\n        font-weight: 420;\n        color: #7c7c7c;\n        border-top: 1px solid #ededed;\n        border-bottom: 1px solid #ededed;\n        padding: 6px 8px;\n    }\n\n    .report-table tbody td {\n        padding: 6px 8px;\n        border-bottom: 1px solid #ededed;\n        vertical-align: top;\n        word-wrap: break-word;\n        font-size: 14px;\n    }\n\n    .report-table thead tr:first-child th:first-child {\n        border-left: 1px solid #ededed;\n        border-top-left-radius: 10px;\n        border-bottom-left-radius: 10px;\n    }\n\n    .report-table thead tr:first-child th:last-child {\n        border-right: 1px solid #ededed;\n        border-top-right-radius: 10px;\n        border-bottom-right-radius: 10px;\n    }\n\n    .report-table tbody tr:last-child td {\n        border-bottom: none;\n    }\n\n    .text-center { text-align: center; }\n    .text-right { text-align: right; font-variant-numeric: tabular-nums; }\n    .text-left { text-align: left; }\n\n    .text-bold { font-weight: 700; }\n    \n    .text-muted { color: #7c7c7c; }\n\n    .report-meta {\n        margin: 10px 0 14px;\n        padding: 8px 10px;\n        color: #171717;\n        font-size: 14px;\n        display: flex;\n        justify-content: space-between;\n        align-items: flex-start;\n        gap: 12px;\n    }\n\n    .report-meta .left,\n    .report-meta .right {\n        display: flex;\n        flex-direction: column;\n    }\n\n    .report-meta .filter-row {\n        margin-bottom: 4px;\n        line-height: 1.5;\n    }\n\n    .report-meta strong {\n        color: #7c7c7c;\n        font-weight: 500;\n    }\n\n    @media print {\n        @page {\n            size: A4;\n            margin-top: 10mm;\n        }\n\n        thead {\n            display: table-header-group;\n        }\n\n        tfoot {\n            display: table-footer-group;\n        }\n\n        tr {\n            page-break-inside: avoid;\n        }\n\n        .no-print {\n            display: none !important;\n        }\n    }\n</style>\n\n<br>\n\n<div>\n\n    <!-- Title -->\n    <div class=\"text-center\" style=\"margin-bottom: 12px;\">\n        <div class=\"title-letter-spacing\">\n            {%= __(report.report_name) %}\n        </div>\n    </div>\n\n    <!-- Meta -->\n    <div class=\"report-meta\">\n        <div class=\"left\">\n            <div>\n                <strong>{%= __(\"Customer\") %}:</strong>\n                {%= (filters.party.length && filters.party.join(\", \")) || __(\"All Parties\") %}\n            </div>\n        </div>\n\n        <div class=\"right text-right\">\n            <div>\n                <strong>{%= __(\"Report Date\") %}:</strong>\n                {%= frappe.datetime.str_to_user(filters.report_date) %}\n            </div>\n        </div>\n    </div>\n\n    <!-- Main Table -->\n    <div class=\"report-table\">\n		<table>\n			<thead>\n				<tr>\n					<th style=\"width: 8em; text-align: left;\">{%= __(\"Date\") %}</th>\n					<th style=\"text-align: left;\">{%= __(\"Reference\") %}</th>\n\n					{% if(filters.show_remarks) { %}\n						<th style=\"text-align: left;\">{%= __(\"Remarks\") %}</th>\n					{% } %}\n\n					<th style=\"width: 10em; text-align: right;\">{%= __(\"Age (Days)\") %}</th>\n					<th style=\"width: 10em; text-align: right;\">{%= __(\"Invoiced Amount\") %}</th>\n					<th style=\"width: 11em; text-align: right;\">{%= __(\"Outstanding Amount\") %}</th>\n				</tr>\n			</thead>\n\n			<tbody>\n				{% for(var i=0, l=data.length; i<l; i++) { %}\n					<tr>\n						<td class=\"text-left\">{%= frappe.datetime.str_to_user(data[i][\"posting_date\"]) %}</td>\n						<td class=\"{% if(i == data.length - 1) { %}text-left text-bold{% } %}\">\n							{% if(i == data.length - 1) { %}\n								{%= __(\"Total\") %}\n							{% } else { %}\n								{%= data[i][\"voucher_no\"] %}\n							{% } %}\n						</td>\n						{% if(filters.show_remarks) { %}\n							<td class=\"text-left\">\n								{% if(data[i][\"remarks\"] && data[i][\"remarks\"] != \"No Remarks\") { %}\n									{%= data[i][\"remarks\"] %}\n								{% } %}\n							</td>\n						{% } %}\n						<td class=\"text-right\">{%= data[i][\"age\"] %}</td>\n						<td class=\"text-right\">{%= format_currency(data[i][\"invoiced\"], data[i][\"currency\"]) %}</td>\n						<td class=\"text-right\">{%= format_currency(data[i][\"outstanding\"], data[i][\"currency\"]) %}</td>\n					</tr>\n				{% } %}\n			</tbody>\n		</table>\n	</div>\n\n	&nbsp;\n\n	{% if(filters.show_future_payments) { %}\n		{%\n			var balance_row = data.slice(-1).pop();\n			var start = report.columns.findIndex(e => e.fieldname == \'age\');\n			var currency = data[data.length - 1][\"currency\"];\n\n			var ranges = [\n				report.columns[start].label,\n				report.columns[start+1].label,\n				report.columns[start+2].label,\n				report.columns[start+3].label,\n				report.columns[start+4].label,\n				report.columns[start+5].label\n			];\n		%}\n\n		{% if(balance_row) { %}\n		<div class=\"report-table\">\n			<table>\n				<thead>\n					<tr>\n						<th style=\"text-align: right;\"></th>\n						{% for(var i = 0; i < ranges.length; i++) { %}\n							<th style=\"text-align: right;\">{%= __(ranges[i]) %}</th>\n						{% } %}\n						<th style=\"text-align: right;\">{%= __(\"Total\") %}</th>\n					</tr>\n				</thead>\n				<tbody>\n					<tr>\n						<td>{%= __(\"Total Outstanding\") %}</td>\n						<td class=\"text-right\">{%= format_number(balance_row[\"age\"], null, 2) %}</td>\n						<td class=\"text-right\">{%= format_currency(balance_row[\"range1\"], currency) %}</td>\n						<td class=\"text-right\">{%= format_currency(balance_row[\"range2\"], currency) %}</td>\n						<td class=\"text-right\">{%= format_currency(balance_row[\"range3\"], currency) %}</td>\n						<td class=\"text-right\">{%= format_currency(balance_row[\"range4\"], currency) %}</td>\n						<td class=\"text-right\">{%= format_currency(balance_row[\"range5\"], currency) %}</td>\n						<td class=\"text-right\">{%= format_currency(flt(balance_row[\"outstanding\"]), currency) %}</td>\n					</tr>\n				</tbody>\n			</table>\n		</div>\n		{% } %}\n	{% } %}\n\n    <p class=\"text-right text-muted\">\n        {%= __(\"Printed on {0}\", [\n            frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())\n        ]) %}\n    </p>\n\n</div>',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
