ng: 6px 8px;\n        font-size: 14px;\n        border-top: 1px solid #ededed;\n        border-bottom: 1px solid #ededed;\n    }\n\n    .report-table thead th {\n        background: #f8f8f8;\n        font-weight: 420;\n        color: #7c7c7c;\n    }\n\n    .report-table tbody td {\n        vertical-align: top;\n        word-wrap: break-word;\n        border-top: none;\n        border-bottom: 1px solid #ededed;\n    }\n    \n    .report-table tbody tr {\n        height: 43px;\n    }\n\n    .report-table thead tr:first-child th:first-child {\n        border-left: 1px solid #ededed;\n        border-top-left-radius: 10px;\n        border-bottom-left-radius: 10px;\n    }\n\n    .report-table thead tr:first-child th:last-child {\n        border-right: 1px solid #ededed;\n        border-top-right-radius: 10px;\n        border-bottom-right-radius: 10px;\n    }\n\n    .report-table tbody tr:last-child td {\n        border-bottom: none;\n    }\n\n    @media print {\n        @page {\n            size: A4;\n            margin-top: 10mm;\n        }\n\n        thead {\n            display: table-header-group;\n        }\n\n        tfoot {\n            display: table-footer-group;\n        }\n\n        tr {\n            page-break-inside: avoid;\n        }\n    }\n</style>\n\n<div>\n\n	<div class=\"text-center\" style=\"margin-bottom: 12px;\">\n		<div class=\"title-letter-spacing\">\n			{%= __(report.report_name) %}\n		</div>\n	</div>\n\n	{% if (subtitle && subtitle.trim()) { %}\n        <div class=\"report-subtitle\">\n            {{ subtitle }}\n        </div>\n    {% } else { %}\n        <div class=\"report-meta\">\n            <div class=\"left\">\n                <div>\n                    <strong>{%= __(\"Company\") %}:</strong> {%= filters.company %}\n                </div>\n                <div>\n                    <strong>{%= __(\"Currency\") %}:</strong>\n                    {%= filters.presentation_currency || erpnext.get_currency(filters.company) %}\n                </div>\n            </div>\n\n            <div class=\"right text-right\">\n                <div>\n                    <strong>{%= __(\"Period Based On\") %}:</strong>\n                    {%= filters.filter_based_on %}\n                </div>\n\n                {% if (filters.filter_based_on === \"Fiscal Year\") { %}\n                    <div>\n                        <strong>{%= __(\"Start Year\") %}:</strong> {%= filters.from_fiscal_year %}\n                    </div>\n                    <div>\n                        <strong>{%= __(\"End Year\") %}:</strong> {%= filters.to_fiscal_year %}\n                    </div>\n\n                {% } else if (filters.filter_based_on === \"Date Range\") { %}\n                    <div>\n                        <strong>{%= __(\"Start Date\") %}:</strong>\n                        {%= frappe.datetime.str_to_user(filters.period_start_date) %}\n                    </div>\n                    <div>\n                        <strong>{%= __(\"End Date\") %}:</strong>\n                        {%= frappe.datetime.str_to_user(filters.period_end_date) %}\n                    </div>\n                {% } %}\n            </div>\n        </div>\n    {% } %}\n\n	<div class=\"report-table\">\n    	<table>\n    		<thead>\n    			<tr>\n    				{% for (let i = 0, l = report_columns.length; i < l; i++) { %}\n    					{%\n    						const col = report_columns[i];\n    						const align = i === 0 ? \"text-left\" : \"text-right\";\n    					%}\n    					<th class=\"{%= align %}\">\n    						{%= col.label %}\n    					</th>\n    				{% } %}\n    			</tr>\n    		</thead>\n    \n    		<tbody>\n    			{% for (let j = 0, k = data.length; j < k; j++) { %}\n    				{%\n    					const row = data[j];\n    \n    					let row_class = \"\";\n    					if (!(row.parent_account || row.parent_section)) {\n    						row_class = \"financial-statements-important\";\n    					}\n    				%}\n    \n    				<tr class=\"{%= row_class %}\">\n    					{% for (let i = 0, l = report_columns.length; i < l; i++) { %}\n    						{%\n    							const col = report_columns[i];\n    							const value = row[col.fieldname];\n    							const align = i === 0 ? \"text-left\" : \"text-right\";\n    						%}\n    \n    						<td class=\"{%= align %}\">\n    							{% if (i === 0) { %}\n    								<span style=\"padding-left: {%= cint(row.indent) * 2 %}em\">\n	                                   {%= String(row.account_name || row.section || \"\").replace(/^[\'\"]|[\'\"]$/g, \"\") %}\n    								</span>\n    							{% } else if (!is_null(value)) { %}\n    								{%= frappe.format(value, col, {}, row) %}\n    							{% } %}\n    						</td>\n    					{% } %}\n    				</tr>\n    			{% } %}\n    		</tbody>\n    	</table>\n    </div>\n\n	<p class=\"text-right text-muted\">\n		{%= __(\"Printed on {0}\", [\n			frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())\n		]) %}\n	</p>\n\n</div>',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Cheque Printing Format','2012-04-11 13:16:56.000000','2015-05-29 01:57:51.203850','Administrator','Administrator',0,1,NULL,'Journal Entry',NULL,NULL,NULL,'Yes',1,0,NULL,'Jinja',0,'<div style=\"position: relative\">\n\n	{%- from \"templates/print_formats/standard_macros.html\" import add_header -%}\n<div class=\"page-break\">\n    {%- if not doc.get(\"print_heading\") and not doc.get(\"select_print_heading\") \n        and doc.set(\"select_print_heading\", _(\"Payment Advice\")) -%}{%- endif -%}\n    {{ add_header(0, 1, doc, letter_head, no_letterhead) }}\n\n{%- for label, value in (\n        (_(\"Voucher Date\"), frappe.utils.formatdate(doc.voucher_date)),\n        (_(\"Reference / Cheque No.\"), doc.cheque_no),\n        (_(\"Reference / Cheque Date\"), frappe.utils.formatdate(doc.cheque_date))\n    ) -%}\n    <div class=\"row\">\n        <div class=\"col-xs-4\"><label class=\"text-right\">{{ label }}</label></div>\n        <div class=\"col-xs-8\">{{ value }}</div>\n    </div>\n{%- endfor -%}\n	<hr>\n	<p>{{ _(\"This amount is in full / part settlement of the listed bills\") }}:</p>\n{%- for label, value in (\n         (_(\"Amount\"), \"<strong>\" + doc.get_formatted(\"total_amount\") + \"</strong><br>\" + (doc.total_amount_in_words or \"\") + \"<br>\"),\n        (_(\"References\"), doc.remark)\n    ) -%}\n    <div class=\"row\">\n        <div class=\"col-xs-4\"><label class=\"text-right\">{{ label }}</label></div>\n        <div class=\"col-xs-8\">{{ value }}</div>\n    </div>\n    {%- endfor -%}\n    <hr>\n	<div style=\"position: absolute; top: 14cm; left: 0cm;\">\n		Prepared By</div>\n	<div style=\"position: absolute; top: 14cm; left: 5.5cm;\">\n		Authorised Signatory</div>\n	<div style=\"position: absolute; top: 14cm; left: 11cm;\">\n		Received Payment as Above</div>\n	<div style=\"position: absolute; top: 16.4cm; left: 5.9cm;\">\n		<strong>_____________</strong></div>\n	<div style=\"position: absolute; top: 16.7cm; left: 6cm;\">\n		<strong>A/C Payee</strong></div>\n	<div style=\"position: absolute; top: 16.7cm; left: 5.9cm;\">\n		<strong>_____________</strong></div>\n	<div style=\"position: absolute; top: 16.9cm; left: 12cm;\">\n		{{ frappe.utils.formatdate(doc.cheque_date) }}</div>\n	<div style=\"position: absolute; top: 17.9cm; left: 1cm;\">\n		{{ doc.pay_to_recd_from }}</div>\n	<div style=\"position: absolute; top: 18.6cm; left: 1cm; width: 7cm;\">\n		{{ doc.total_amount_in_words }}</div>\n	<div style=\"position: absolute; top: 19.7cm; left: 12cm;\">\n		{{ doc.get_formatted(\"total_amount\") }}</div>\n</div>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Credit Note','2014-08-28 11:11:39.796473','2019-04-18 12:10:14.732269','Administrator','Administrator',0,2,NULL,'Journal Entry',NULL,'Accounts',NULL,'Yes',0,0,NULL,'Jinja',0,'{%- from \"templates/print_formats/standard_macros.html\" import add_header -%}\n\n<div class=\"page-break\">\n    {%- if not doc.get(\"print_heading\") and not doc.get(\"select_print_heading\") \n        and doc.set(\"select_print_heading\", _(\"Credit Note\")) -%}{%- endif -%}\n    {{ add_header(0, 1, doc, letter_head, no_letterhead) }}\n\n    {%- for label, value in (\n        (_(\"Credit To\"), doc.pay_to_recd_from),\n        (_(\"Date\"), frappe.utils.formatdate(doc.voucher_date)),\n        (_(\"Amount\"), \"<strong>\" + doc.get_formatted(\"total_amount\") + \"</strong><br>\" + (doc.total_amount_in_words or \"\") + \"<br>\"),\n        (_(\"Remarks\"), doc.remark)\n    ) -%}\n\n    <div class=\"row\">\n        <div class=\"col-xs-3\"><label class=\"text-right\">{{ label }}</label></div>\n        <div class=\"col-xs-9\">{{ value }}</div>\n    </div>\n\n    {%- endfor -%}\n\n    <hr>\n    <br>\n    <p class=\"strong\">\n        {{ _(\"For\") }} {{ doc.company }},<br>\n        <br>\n        <br>\n        <br>\n        {{ _(\"Authorized Signatory\") }}\n    </p>\n</div>\n\n\n',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,NULL,NULL,NULL,'[{\"fieldname\": \"print_heading_template\", \"fieldtype\": \"Custom HTML\", \"options\": \"<div class=\\\"print-heading\\\">\\t\\t\\t\\t<h2>Journal Entry<br><small>{{ doc.name }}</small>\\t\\t\\t\\t</h2></div>\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"voucher_type\", \"print_hide\": 0, \"label\": \"Entry Type\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"posting_date\", \"print_hide\": 0, \"label\": \"Posting Date\"}, {\"fieldname\": \"finance_book\", \"print_hide\": 0, \"label\": \"Finance Book\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"accounts\", \"print_hide\": 0, \"label\": \"Accounting Entries\", \"visible_columns\": [{\"fieldname\": \"account\", \"print_width\": \"250px\", \"print_hide\": 0}, {\"fieldname\": \"bank_account_no\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"party_type\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"party\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"debit_in_account_currency\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"credit_in_account_currency\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"reference_type\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"reference_name\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"reference_due_date\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"project\", \"print_width\": \"\", \"print_hide\": 0}]}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"cheque_no\", \"print_hide\": 0, \"label\": \"Reference Number\"}, {\"fieldname\": \"cheque_date\", \"print_hide\": 0, \"label\": \"Reference Date\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"get_balance\", \"print_hide\": 0, \"label\": \"Make Difference Entry\"}, {\"fieldname\": \"total_amount\", \"print_hide\": 0, \"label\": \"Total Amount\"}, {\"fieldtype\": \"Section Break\", \"label\": \"Reference\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"clearance_date\", \"print_hide\": 0, \"label\": \"Clearance Date\"}, {\"fieldname\": \"remark\", \"print_hide\": 0, \"label\": \"Remark\"}, {\"fieldname\": \"inter_company_journal_entry_reference\", \"print_hide\": 0, \"label\": \"Inter Company Journal Entry Reference\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"due_date\", \"print_hide\": 0, \"label\": \"Due Date\"}, {\"fieldtype\": \"Section Break\", \"label\": \"Printing Settings\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"pay_to_recd_from\", \"print_hide\": 0, \"label\": \"Pay To / Recd From\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"letter_head\", \"print_hide\": 0, \"label\": \"Letter Head\"}, {\"fieldtype\": \"Section Break\", \"label\": \"More Information\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"mode_of_payment\", \"print_hide\": 0, \"label\": \"Mode of Payment\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"stock_entry\", \"print_hide\": 0, \"label\": \"Stock Entry\"}]',0,0,NULL,NULL,NULL,NULL),
('Delivery Note Standard','2025-11-30 16:53:24.456411','2026-07-03 02:26:31.243291','Administrator','Administrator',0,0,'DocType','Delivery Note',NULL,'Stock','en','Yes',1,0,'wkhtmltopdf','Jinja',0,'{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}\n	{% if letter_head and not no_letterhead %}\n		<div class=\"letter-head\">{{ letter_head }}</div>\n	{% endif %}\n	{% if print_heading_template %}\n		{{ frappe.render_template(print_heading_template, {\"doc\":doc}) }}\n	{% endif %}\n{%- endmacro -%}\n\n{% for page in layout %}\n<div class=\"page-break invoice-wrapper\">\n	<div {% if print_settings.repeat_header_footer %} id=\"header-html\" class=\"hidden-pdf\" {% endif %}>\n		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}\n	</div>\n	{%- if doc.meta.is_submittable and doc.docstatus==2-%}\n		<div class=\"text-center\" document-status=\"cancelled\">\n			<h4 style=\"margin-top: 20px;\">{{ _(\"CANCELLED\") }}</h4>\n		</div>\n	{%- endif -%}\n	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}\n		<div class=\"text-center\" document-status=\"draft\">\n			<h4 style=\"margin-top: 20px !important;\">{{ _(\"DRAFT\") }}</h4>\n		</div>\n	{%- endif -%}\n\n	<style>\n		.letter-head {\n			margin-top: 12px !important;\n		}\n		.invoice-wrapper {\n			font-family: \"Inter\", sans-serif;\n			color: var(--black-overlay-700);\n		}\n\n		.print-format-body {\n			padding: 30px 12px 12px 12px !important;\n		}\n\n		body {\n			margin-bottom: 0mm !important;\n			padding: 0px !important;\n		}\n\n		table.info-table,\n		table.items-table,\n		table.tax-table {\n			border-collapse: separate;\n			border-spacing: 0;\n			border: 1px solid #ededed;\n			border-radius: 10px;\n			overflow: hidden;\n		}\n\n		table.info-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px 10px !important;\n		}\n		table.items-table td,\n		table.tax-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px;\n		}\n\n		table.info-table td:not(:first-of-type),\n		table.items-table td:not(:first-of-type),\n		table.tax-table td:not(:first-of-type) {\n			border-left: 1px solid #ededed;\n		}\n\n		table.info-table tbody tr:last-of-type td,\n		table.items-table tbody tr:last-of-type td,\n		table.tax-table tbody tr:last-of-type td {\n			border-bottom: none;\n		}\n\n		thead.table-header {\n			background: #f8f8f8;\n		}\n		thead.table-header td {\n			color: #7c7c7c;\n		}\n\n		.text-center {\n			text-align: center;\n		}\n		.text-left {\n			text-align: left;\n		}\n		.text-right {\n			text-align: right;\n		}\n		.text-muted {\n			color: #7c7c7c;\n		}\n		.text-dark {\n			color: #525252;\n		}\n		.text-bold {\n			font-weight: bold;\n		}\n		.small-text {\n			color: #666;\n		}\n\n		.mt-10 {\n			margin-top: 10px;\n		}\n		.mt-15 {\n			margin-top: 15px;\n		}\n		.mt-20 {\n			margin-top: 20px;\n		}\n		.mt-40 {\n			margin-top: 40px;\n		}\n		.mt-80 {\n			margin-top: 80px;\n		}\n		.mb-20 {\n			margin-bottom: 20px;\n		}\n		.pb-8 {\n			padding-bottom: 8px;\n		}\n		.amount-width {\n			width: 110px;\n		}\n\n		.totals-table {\n			border-radius: 5px;\n			width: 100%;\n		}\n		.totals-table td {\n			padding: 4px 8px;\n		}\n		.totals-table tr {\n			border-bottom: 1px solid #ededed;\n			position: relative;\n		}\n		.totals-table tr td {\n			position: relative;\n		}\n		.totals-table tr td div {\n			width: 12%;\n			height: 14px;\n			background-color: white;\n			position: absolute;\n			bottom: -6px;\n			left: 0%;\n			color: white;\n		}\n		.totals-table tr:last-child {\n			border-bottom: none;\n		}\n		.totals-table .grand-total td {\n			padding: 6px 8px;\n			font-weight: bold;\n		}\n\n		.words-box {\n			background: #f8f8f8;\n			border-radius: 8px;\n			padding: 8px;\n			line-height: 21px;\n			letter-spacing: 0.21px;\n			font-size: small;\n		}\n\n		.info-card {\n			color: #7c7c7c;\n		}\n\n		.title {\n			color: #7c7c7c !important;\n		}\n\n		.heading {\n			color: #525252 !important;\n			font-weight: 300;\n		}\n\n		.print-format {\n			color: #171717;\n			font-size: 14px;\n			font-style: normal;\n			font-weight: 420;\n			line-height: 21px;\n			padding: 0px;\n			letter-spacing: 0.14px;\n			margin-left: 0mm !important;\n			margin-right: 0mm !important;\n		}\n		.letter-head-footer {\n			margin-top: 0px !important;\n		}\n		.print-heading {\n			margin-top: 0px !important;\n			margin-bottom: 0px !important;\n			padding-bottom: 0px !important;\n		}\n	</style>\n	<div class=\"print-format-body\">\n		<table class=\"info-table mb-20\" style=\"width: 100%\">\n			<tr>\n				<td style=\"width: 50%\">\n					<span class=\"heading\">{{ _(\"Customer Name\") }}:</span> {{doc.customer_name }}\n				</td>\n				<td style=\"width: 50%\">\n					<span class=\"heading\">{{ _(\"Status\") }}:</span> {{ doc.status }}\n				</td>\n			</tr>\n			<tr>\n				<td><span class=\"heading\">{{ _(\"Delivery Note\") }}:</span> {{ doc.name }}</td>\n				<td>\n					<span class=\"heading\">{{ _(\"Date\") }}:</span> {{\n					frappe.utils.format_date(doc.posting_date) }}\n				</td>\n			</tr>\n			<tr>\n				<td><span class=\"heading\">{{ _(\"Company Address\") }}:</span><br />\n					{% if doc.company_address %}\n                        {% set company_address = frappe.db.get_value(\"Address\", doc.company_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n                        {{  doc.company }}<br>\n                        {{ company_address.get(\"address_line1\") or \"\" }}<br>\n                        {% if company_address.get(\"address_line2\") %}{{ company_address.get(\"address_line2\") }}<br>{% endif %}\n                        {{ company_address.get(\"city\") or \"\" }}, {{ company_address.get(\"state\") or \"\" }} {{ company_address.get(\"pincode\") or \"\" }}, {{ company_address.get(\"country\") or \"\" }}<br>\n                    {% endif %}\n				</td>\n				<td><span class=\"heading\">{{ _(\"Customer Address\") }}:</span><br />\n				    {% if doc.customer_address %}\n						{% set customer_address = frappe.db.get_value(\"Address\", doc.customer_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n                        {{ doc.customer_name }}<br>\n						{{ customer_address.address_line1 or \"\" }}<br>\n						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}\n						{{ customer_address.city or \"\" }} {{ customer_address.state or \"\" }} {{ customer_address.pincode or \"\" }} {{ customer_address.country or \"\" }}<br>\n					{% endif %}\n				</td>\n			</tr>\n		</table>\n\n		<!-- Items Table -->\n		{% set item_naming_by = frappe.db.get_single_value(\"Stock Settings\", \"item_naming_by\") %}\n		<table class=\"items-table mt-15\" style=\"width: 100%\">\n			<thead class=\"table-header\">\n				<tr>\n					<td class=\"text-center\">{{ _(\"No\") }}</td>\n					<td class=\"text-left\">{{ _(\"Item\") }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ _(\"Item Code\") }}</td>\n					{% endif %}\n					<td class=\"text-right\">{{ _(\"Quantity\") }}</td>\n					<td class=\"text-right\">{{ _(\"Rate\") }}</td>\n					<td class=\"text-right\">{{ _(\"Amount\") }}</td>\n				</tr>\n			</thead>\n			<tbody>\n				{% for item in doc.items %}\n				<tr>\n					<td class=\"text-center text-dark\">{{ loop.index }}</td>\n					<td>{{ item.item_name }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ item.item_code }}</td>\n					{% endif %}\n					<td class=\"text-right text-dark\">{{ item.get_formatted(\"qty\", 0) }} {{ item.uom }}</td>\n					<td class=\"text-right text-dark\">{{ item.get_formatted(\"net_rate\", doc) }}</td>\n					<td class=\"text-right\" style=\"color: #171717\">\n						{{ item.get_formatted(\"net_amount\", doc) }}\n					</td>\n				</tr>\n				{% endfor %}\n			</tbody>\n		</table>\n\n		<!-- Totals Section -->\n		<table style=\"width:100%; margin-top: 15px\">\n			<td style=\"vertical-align: bottom !important; width: 60%;\">\n				<p class=\"title\">{{ _(\"Total in words\") }}</p>\n				<div class=\"words-box text-uppercase\">{{ doc.in_words }}</div>\n			</td>\n			<td>\n				&nbsp;\n			</td>\n			<td style=\"width: 38%;\">\n				<table class=\"totals-table\">\n					<tr>\n						<td class=\"text-right text-muted\"><div></div>{{ _(\"Sub Total:\") }}</td>\n						<td class=\"text-right amount-width\">{{ doc.get_formatted(\"total\", doc) }}</td>\n					</tr>\n					{%- if doc.apply_discount_on == \"Net Total\" -%}\n						<tr>\n							<td class=\"text-right text-muted\">\n								<div></div>{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n							</td>\n							<td class=\"text-right amount-width\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n						</tr>\n					{%- endif -%}\n					{%- for tax in doc.taxes -%}\n						{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}\n							<tr>\n								<td class=\"text-right text-muted\"><div></div>{{ tax.get_formatted(\"description\") }} ({{ tax.get_formatted(\"rate\") }}%):</td>\n								<td class=\"text-right amount-width\">{{ tax.get_formatted(\"tax_amount\") }}</td>\n							</tr>\n						{%- endif -%}\n					{%- endfor -%}\n					{%- if doc.apply_discount_on == \"Grand Total\" -%}\n						<tr>\n							<td class=\"text-right text-muted\">\n								<div></div>{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n							</td>\n							<td class=\"text-right amount-width\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n						</tr>\n					{%- endif -%}\n					<tr class=\"grand-total\">\n						<td class=\"text-right\">{{ _(\"Grand Total:\") }}</td>\n						<td class=\"text-right amount-width\">{{ doc.get_formatted(\"grand_total\", doc) }}</td>\n					</tr>\n				</table>\n			</td>\n		</table>\n\n		<!-- Terms -->\n		<div class=\"terms-section\">\n			{% if doc.terms %}\n			<div class=\"info-card mt-40\">\n				<div>{{ _(\"Terms and Conditions\") }}</div>\n				{{ doc.terms}}\n			</div>\n			{% endif %}\n	</div>\n	<div {% if print_settings.repeat_header_footer %} id=\"footer-html\" class=\"visible-pdf\" {% endif %}>\n		{% if not no_letterhead and footer %}\n		<div class=\"letter-head-footer\">\n			{{ footer }}\n		</div>\n		{% endif %}\n		{% if print_settings.repeat_header_footer %}\n		<p class=\"text-center small page-number visible-pdf\">\n			{{ _(\"Page {0} of {1}\").format(\'<span class=\"page\"></span>\', \'<span class=\"topage\"></span>\') }}\n		</p>\n		{% endif %}\n	</div>\n</div>\n{% endfor %}',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
