n Break\"}, {\"fieldname\": \"set_from_warehouse\", \"print_hide\": 0, \"label\": \"Set From Warehouse\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"_custom_html\", \"print_hide\": 0, \"label\": \"Custom HTML\", \"fieldtype\": \"HTML\", \"options\": \"<table class=\\\"table table-bordered\\\">\\n\\t<tbody>\\n\\t\\t<tr>\\n\\t\\t\\t<th>Sr</th>\\n\\t\\t\\t<th>Item Name</th>\\n\\t\\t\\t<th>Description</th>\\n\\t\\t\\t<th class=\\\"text-right\\\">Qty</th>\\n\\t\\t\\t<th class=\\\"text-right\\\">Rate</th>\\n\\t\\t\\t<th class=\\\"text-right\\\">Amount</th>\\n\\t\\t</tr>\\n\\t\\t{%- for row in doc.items -%}\\n\\t\\t<tr>\\n\\t\\t    {% set bundle_data = get_serial_or_batch_nos(row.serial_and_batch_bundle) %}\\n\\t\\t    {% set serial_nos = [] %}\\n            {% set batches = {} %}\\n\\n\\t\\t\\t<td style=\\\"width: 4%;\\\">{{ row.idx }}</td>\\n\\t\\t\\t<td style=\\\"width: 20%;\\\">\\n\\t\\t\\t\\t{{ row.item_name }}\\n\\t\\t\\t\\t{% if row.item_code != row.item_name -%}\\n\\t\\t\\t\\t<br>Item Code: {{ row.item_code}}\\n\\t\\t\\t\\t{%- endif %}\\n\\t\\t\\t</td>\\n\\t\\t\\t<td style=\\\"width: 30%;\\\">\\n\\t\\t\\t\\t<div style=\\\"border: 0px;\\\">{{ row.description }}</div></td>\\n\\t\\t\\t<td style=\\\"width: 10%; text-align: right;\\\">{{ row.qty }} {{ row.uom or row.stock_uom }}</td>\\n\\t\\t\\t<td style=\\\"width: 18%; text-align: right;\\\">{{\\n\\t\\t\\t\\trow.get_formatted(\\\"rate\\\", doc) }}</td>\\n\\t\\t\\t<td style=\\\"width: 18%; text-align: right;\\\">{{\\n\\t\\t\\t\\trow.get_formatted(\\\"amount\\\", doc) }}</td>\\n\\t\\t\\t\\n\\t\\t</tr>\\n\\t\\t{%- endfor -%}\\n\\t</tbody>\\n</table>\\n\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"total_qty\", \"print_hide\": 0, \"label\": \"Total Quantity\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"total\", \"print_hide\": 0, \"label\": \"Total\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"taxes\", \"print_hide\": 0, \"label\": \"Purchase Taxes and Charges\", \"visible_columns\": [{\"fieldname\": \"category\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"add_deduct_tax\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"charge_type\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"row_id\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"included_in_print_rate\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"included_in_paid_amount\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"account_head\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"description\", \"print_width\": \"300px\", \"print_hide\": 0}, {\"fieldname\": \"rate\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"region\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"function\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"location\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"cost_center\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"depot\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"country\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"account_currency\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"tax_amount\", \"print_width\": \"\", \"print_hide\": 0}, {\"fieldname\": \"total\", \"print_width\": \"\", \"print_hide\": 0}]}, {\"fieldtype\": \"Section Break\", \"label\": \"Totals\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"grand_total\", \"print_hide\": 0, \"label\": \"Grand Total\"}, {\"fieldname\": \"rounded_total\", \"print_hide\": 0, \"label\": \"Rounded Total\"}, {\"fieldname\": \"in_words\", \"print_hide\": 0, \"label\": \"In Words\"}, {\"fieldname\": \"disable_rounded_total\", \"print_hide\": 0, \"label\": \"Disable Rounded Total\"}, {\"fieldtype\": \"Section Break\", \"label\": \"Supplier Address\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"address_display\", \"print_hide\": 0, \"label\": \"Address\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"contact_display\", \"print_hide\": 0, \"label\": \"Contact\"}, {\"fieldname\": \"contact_mobile\", \"print_hide\": 0, \"label\": \"Mobile No\"}, {\"fieldtype\": \"Section Break\", \"label\": \"Company Billing Address\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"billing_address\", \"print_hide\": 0, \"label\": \"Billing Address\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"billing_address_display\", \"print_hide\": 0, \"label\": \"Billing Address\"}, {\"fieldname\": \"terms\", \"nolabel\": 1, \"print_hide\": 0, \"label\": \"Terms and Conditions\"}, {\"fieldtype\": \"Section Break\", \"label\": \"\"}, {\"fieldtype\": \"Column Break\"}, {\"fieldname\": \"_custom_html\", \"print_hide\": 0, \"label\": \"Custom HTML\", \"fieldtype\": \"HTML\", \"options\": \"<table class=\\\"table table-bordered\\\">\\n\\t<tbody>\\n\\t\\t<tr>\\n\\t\\t\\t<th>Sr</th>\\n\\t\\t\\t<th>Item Name</th>\\n\\t\\t\\t<th>Qty</th>\\n\\t\\t\\t<th class=\\\"text-left\\\">Serial Nos</th>\\n\\t\\t\\t<th class=\\\"text-left\\\">Batch Nos (Qty)</th>\\n\\t\\t</tr>\\n\\t\\t{%- for row in doc.items -%}\\n\\t\\t<tr>\\n\\t\\t    {% set bundle_data = frappe.get_all(\\\"Serial and Batch Entry\\\", \\n\\t\\t        fields=[\\\"serial_no\\\", \\\"batch_no\\\", \\\"qty\\\"], \\n\\t\\t        filters={\\\"parent\\\": row.serial_and_batch_bundle}) %}\\n\\t\\t    {% set serial_nos = [] %}\\n            {% set batches = {} %}\\n            \\n            {% if bundle_data %}\\n\\t\\t\\t    {% for data in bundle_data %}\\n\\t\\t\\t        {% if data.serial_no %}\\n\\t\\t\\t            {{ serial_nos.append(data.serial_no) or \\\"\\\" }}\\n\\t\\t\\t        {% endif %}\\n\\t\\t\\t        \\n\\t\\t\\t        {% if data.batch_no %}\\n\\t\\t\\t            {{ batches.update({data.batch_no: data.qty}) or \\\"\\\" }}\\n\\t\\t\\t        {% endif %}\\n\\t\\t\\t    {% endfor %}\\n\\t\\t\\t{% endif %}\\n\\n\\t\\t\\t<td style=\\\"width: 3%;\\\">{{ row.idx }}</td>\\n\\t\\t\\t<td style=\\\"width: 20%;\\\">\\n\\t\\t\\t\\t{{ row.item_name }}\\n\\t\\t\\t\\t{% if row.item_code != row.item_name -%}\\n\\t\\t\\t\\t<br>Item Code: {{ row.item_code}}\\n\\t\\t\\t\\t{%- endif %}\\n\\t\\t\\t</td>\\n\\t\\t\\t<td style=\\\"width: 10%; text-align: right;\\\">{{ row.qty }} {{ row.uom or row.stock_uom }}</td>\\n\\t\\t\\t\\n\\t\\t\\t<td style=\\\"width: 30%; text-align: left;\\\">{{ serial_nos|join(\',\') }}</td>\\n\\t\\t\\t<td style=\\\"width: 30%;\\\">\\n\\t\\t\\t    {% if batches %}\\n                    {% for batch_no, qty in batches.items() %}\\n                        <p> {{batch_no}} : {{qty}} {{ row.uom or row.stock_uom }} </p>\\n                    {% endfor %}\\n                {% endif %}\\n\\t\\t\\t</td>\\n\\t\\t\\t\\n\\t\\t</tr>\\n\\t\\t{%- endfor -%}\\n\\t</tbody>\\n</table>\\n\"}]',1,0,NULL,NULL,NULL,NULL),
('QR Code','2026-07-13 16:51:28.236869','2026-07-13 17:01:15.656027','Administrator','Administrator',0,0,'DocType','Pick List',NULL,'Stock','en','Yes',1,0,'wkhtmltopdf','Jinja',0,'{% if print_data %}\n<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>QR Code Labels</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n        body {\n            font-family: \'Arial\', sans-serif;\n            background: #fff;\n            padding: 10mm;\n        }\n        .label-container {\n            display: flex;\n            width: 100%;\n            height: 100mm;\n            border: 2px solid #000;\n            border-radius: 15px;\n            overflow: hidden;\n            margin-bottom: 15mm;\n            page-break-inside: avoid;\n            background: #fff;\n        }\n        \n        /* Left Section - White Background */\n        .left-section {\n            flex: 2;\n            background-color: #ffffff;\n            padding: 12mm;\n            display: flex;\n            flex-direction: column;\n            justify-content: space-between;\n            border-right: 1px solid #000;\n        }\n        \n        .detail-group {\n            display: flex;\n            margin-bottom: 3mm;\n            align-items: baseline;\n            font-size: 11pt;\n            font-weight: 600;\n            color: #1a1a3e;\n        }\n        \n        .detail-label {\n            min-width: 45mm;\n            margin-right: 2mm;\n        }\n        \n        .detail-value {\n            flex: 1;\n        }\n        \n        .special-note {\n            font-size: 8pt;\n            color: #666;\n            margin-bottom: 2mm;\n        }\n        \n        .qr-section {\n            display: flex;\n            gap: 5mm;\n            justify-content: center;\n            align-items: flex-start;\n        }\n        \n        .qr-item {\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            gap: 2mm;\n        }\n        \n        .qr-code {\n            width: 30mm;\n            height: 30mm;\n            border: 2px solid #000;\n            padding: 2mm;\n            background: #fff;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n        \n        .qr-code img {\n            max-width: 100%;\n            max-height: 100%;\n            width: auto;\n            height: auto;\n        }\n        \n        .serial-text {\n            font-size: 9pt;\n            font-weight: bold;\n            color: #000;\n            text-align: center;\n            letter-spacing: 1px;\n        }\n        \n        /* Middle Section - Vertical White Text */\n        .middle-section {\n            flex: 0.3;\n            background-color: #ffffff;\n            padding: 8mm;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            border-right: 1px solid #000;\n            writing-mode: vertical-rl;\n            text-orientation: mixed;\n            transform: rotate(180deg);\n        }\n        \n        .middle-text {\n            font-size: 7pt;\n            font-weight: 600;\n            color: #1a1a3e;\n            line-height: 1.4;\n            text-align: center;\n            white-space: pre-wrap;\n        }\n        \n        /* Right Section - Navy Blue Background */\n        .right-section {\n            flex: 0.5;\n            background-color: #1a1a4d;\n            padding: 8mm;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            writing-mode: vertical-rl;\n            text-orientation: mixed;\n            transform: rotate(180deg);\n        }\n        \n        .company-info {\n            color: #ffffff;\n            font-size: 7pt;\n            font-weight: 600;\n            line-height: 1.6;\n            text-align: center;\n            white-space: pre-wrap;\n        }\n        \n        @media print {\n            body {\n                padding: 5mm;\n            }\n            .label-container {\n                margin-bottom: 10mm;\n            }\n        }\n    </style>\n</head>\n<body>\n    {% for item in print_data %}\n    <div class=\"label-container\">\n        <!-- Left Section -->\n        <div class=\"left-section\">\n            <div>\n                <div class=\"detail-group\">\n                    <span class=\"detail-label\">SORT:</span>\n                    <span class=\"detail-value\">{{ item.sort or \'-\' }}</span>\n                </div>\n                <div class=\"detail-group\">\n                    <span class=\"detail-label\">SHADE:</span>\n                    <span class=\"detail-value\">{{ item.shade or \'-\' }}</span>\n                </div>\n                <div class=\"detail-group\">\n                    <span class=\"detail-label\">SIZE:</span>\n                    <span class=\"detail-value\">{{ item.size or \'-\' }}</span>\n                </div>\n                <div class=\"detail-group\">\n                    <span class=\"detail-label\">STYLE:</span>\n                    <span class=\"detail-value\">{{ item.style or \'-\' }} &nbsp; B BF</span>\n                </div>\n                <div class=\"detail-group\">\n                    <span class=\"detail-label\">QTY:</span>\n                    <span class=\"detail-value\">{{ item.qty }}</span>\n                </div>\n                <div class=\"detail-group\">\n                    <span class=\"detail-label\">MRP:</span>\n                    <span class=\"detail-value\">Rs.{{ \"%.2f\"|format(item.mrp) }}</span>\n                </div>\n                <div class=\"special-note\">(MG OF ALLM)</div>\n            </div>\n            \n            <div class=\"qr-section\">\n                {% set qr_master = frappe.call(\'frappe.client.get\', doctype=\'Pick List\', name=doc.name) %}\n                <div class=\"qr-item\">\n                    <div class=\"qr-code\">\n                        <img src=\"data:image/svg+xml;base64,\" alt=\"QR Code\">\n                    </div>\n                    <span class=\"serial-text\">{{ item.item_master_serial_no }}</span>\n                </div>\n                <div class=\"qr-item\">\n                    <div class=\"qr-code\">\n                        <img src=\"data:image/svg+xml;base64,\" alt=\"QR Code\">\n                    </div>\n                    <span class=\"serial-text\">{{ item.item_price_serial_no }}</span>\n                </div>\n            </div>\n        </div>\n        \n        <!-- Middle Section -->\n        <div class=\"middle-section\">\n            <div class=\"middle-text\">Consumer is free to open and inspect product before buying !!</div>\n        </div>\n        \n        <!-- Right Section -->\n        <div class=\"right-section\">\n            <div class=\"company-info\">OUTESSENTIALS (AUNT OF OTTO CLOTHING PVT DID)\nRegd. Head Office\nGERO\nReso\nOFFICE SF BLDG.6 63,1501 1961:144,8 1st KNOW1 IMAX KAMNATH JAMNATH\nRed Ported From email\nID</div>\n        </div>\n    </div>\n    {% endfor %}\n</body>\n</html>\n{% else %}\n<div style=\"padding: 20px; text-align: center; color: #d32f2f;\">\n    <strong>Error:</strong> No print data available. Please generate QR codes first.\n</div>\n{% endif %}',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Quotation Standard','2026-03-18 11:47:51.934541','2026-07-03 02:26:31.243291','Administrator','Administrator',0,0,'DocType','Quotation',NULL,'Selling','en','Yes',1,0,'wkhtmltopdf','Jinja',0,'\n\n{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}\n	{% if letter_head and not no_letterhead %}\n		<div class=\"letter-head\">{{ letter_head }}</div>\n	{% endif %}\n	{% if print_heading_template %}\n		{{ frappe.render_template(print_heading_template, {\"doc\":doc}) }}\n	{% endif %}\n{%- endmacro -%}\n\n{% for page in layout %}\n<div class=\"page-break invoice-wrapper\">\n	<div {% if print_settings.repeat_header_footer %} id=\"header-html\" class=\"hidden-pdf\" {% endif %}>\n		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}\n	</div>\n	{%- if doc.meta.is_submittable and doc.docstatus==2-%}\n		<div class=\"text-center\" document-status=\"cancelled\">\n			<h4 style=\"margin-top: 20px;\">{{ _(\"CANCELLED\") }}</h4>\n		</div>\n	{%- endif -%}\n	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}\n		<div class=\"text-center\" document-status=\"draft\">\n			<h4 style=\"margin-top: 20px !important;\">{{ _(\"DRAFT\") }}</h4>\n		</div>\n	{%- endif -%}\n\n	<style>\n		.letter-head {\n			margin-top: 12px !important;\n		}\n		.invoice-wrapper {\n			font-family: \"Inter\", sans-serif;\n			color: var(--black-overlay-700);\n		}\n\n		.print-format-body {\n			padding: 30px 12px 12px 12px !important;\n		}\n\n		body {\n			margin-bottom: 0mm !important;\n			padding: 0px !important;\n		}\n\n		table.info-table,\n		table.items-table,\n		table.tax-table {\n			border-collapse: separate;\n			border-spacing: 0;\n			border: 1px solid #ededed;\n			border-radius: 10px;\n			overflow: hidden;\n		}\n\n		table.info-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px 10px !important;\n		}\n		table.items-table td,\n		table.tax-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px;\n		}\n\n		table.info-table td:not(:first-of-type),\n		table.items-table td:not(:first-of-type),\n		table.tax-table td:not(:first-of-type) {\n			border-left: 1px solid #ededed;\n		}\n\n		table.info-table tbody tr:last-of-type td,\n		table.items-table tbody tr:last-of-type td,\n		table.tax-table tbody tr:last-of-type td {\n			border-bottom: none;\n		}\n\n		thead.table-header {\n			background: #f8f8f8;\n		}\n		thead.table-header td {\n			color: #7c7c7c;\n		}\n\n		.text-center {\n			text-align: center;\n		}\n		.text-left {\n			text-align: left;\n		}\n		.text-right {\n			text-align: right;\n		}\n		.text-muted {\n			color: #7c7c7c;\n		}\n		.text-dark {\n			color: #525252;\n		}\n		.text-bold {\n			font-weight: bold;\n		}\n		.small-text {\n			color: #666;\n		}\n\n		.mt-10 {\n			margin-top: 10px;\n		}\n		.mt-15 {\n			margin-top: 15px;\n		}\n		.mt-20 {\n			margin-top: 20px;\n		}\n		.mt-40 {\n			margin-top: 40px;\n		}\n		.mt-80 {\n			margin-top: 80px;\n		}\n		.mb-20 {\n			margin-bottom: 20px;\n		}\n		.pb-8 {\n			padding-bottom: 8px;\n		}\n		.amount-width {\n			width: 110px;\n		}\n\n		.totals-table {\n			border-radius: 5px;\n			width: 100%;\n		}\n		.totals-table td {\n			padding: 4px 8px;\n		}\n		.totals-table tr {\n			border-bottom: 1px solid #ededed;\n			position: relative;\n		}\n		.totals-table tr td {\n			position: relative;\n		}\n		.totals-table tr td div {\n			width: 12%;\n			height: 14px;\n			background-color: white;\n			position: absolute;\n			bottom: -6px;\n			left: 0%;\n			color: white;\n		}\n		.totals-table tr:last-child {\n			border-bottom: none;\n		}\n		.totals-table .grand-total td {\n			padding: 6px 8px;\n			font-weight: bold;\n		}\n\n		.words-box {\n			background: #f8f8f8;\n			border-radius: 8px;\n			padding: 8px;\n			line-height: 21px;\n			letter-spacing: 0.21px;\n			font-size: small;\n		}\n\n		.info-card {\n			color: #7c7c7c;\n		}\n\n		.title {\n			color: #7c7c7c !important;\n		}\n\n		.heading {\n			color: #525252 !important;\n			font-weight: 300;\n		}\n\n		.print-format {\n			color: #171717;\n			font-size: 14px;\n			font-style: normal;\n			font-weight: 420;\n			line-height: 21px;\n			padding: 0px;\n			letter-spacing: 0.14px;\n			margin-left: 0mm !important;\n			margin-right: 0mm !important;\n		}\n		.letter-head-footer {\n			margin-top: 0px !important;\n		}\n		.print-heading {\n			margin-top: 0px !important;\n			margin-bottom: 0px !important;\n			padding-bottom: 0px !important;\n		}\n	</style>\n	<div class=\"print-format-body\">\n		<table class=\"info-table mb-20\" style=\"width: 100%\">\n			<tr>\n				<td style=\"width: 50%\">\n					<span class=\"heading\">{{ _(\"Party Name\") }}:</span> {{doc.party_name }}\n				</td>\n				<td style=\"width: 50%\">\n					<span class=\"heading\">{{ _(\"Valid Till\") }}:</span> {{\n					frappe.utils.format_date(doc.valid_till) }}\n				</td>\n			</tr>   \n			<tr>\n				<td><span class=\"heading\">{{ _(\"Quotation\") }}:</span> {{ doc.name }}</td>\n				<td>\n					<span class=\"heading\">{{ _(\"Posting Date\") }}:</span> {{\n					frappe.utils.format_date(doc.transaction_date) }}\n				</td>\n			</tr>\n			<tr>\n				<td><span class=\"heading\">{{ _(\"Bill From\") }}:</span><br />\n					{% if doc.company_address %}\n                        {% set company_address = frappe.db.get_value(\"Address\", doc.company_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n                        {{  doc.company }}<br>\n                        {{ company_address.get(\"address_line1\") or \"\" }}<br>\n                        {% if company_address.get(\"address_line2\") %}{{ company_address.get(\"address_line2\") }}<br>{% endif %}\n                        {{ company_address.get(\"city\") or \"\" }}, {{ company_address.get(\"state\") or \"\" }} {{ company_address.get(\"pincode\") or \"\" }}, {{ company_address.get(\"country\") or \"\" }}<br>\n                    {% endif %}\n				</td>\n				<td><span class=\"heading\">{{ _(\"Bill To\") }}:</span><br />\n				    {% if doc.customer_address %}\n						{% set customer_address = frappe.db.get_value(\"Address\", doc.customer_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n                        {{ doc.customer_name }}<br>\n						{{ customer_address.address_line1 or \"\" }}<br>\n						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}\n						{{ customer_address.city or \"\" }} {{ customer_address.state or \"\" }} {{ customer_address.pincode or \"\" }} {{ customer_address.country or \"\" }}<br>\n					{% endif %}\n				</td>\n			</tr>\n		</table>\n\n		<!-- Items Table -->\n		{% set item_naming_by = frappe.db.get_single_value(\"Stock Settings\", \"item_naming_by\") %}\n		<table class=\"items-table mt-15\" style=\"width: 100%\">\n			<thead class=\"table-header\">\n				<tr>\n					<td class=\"text-center\">{{ _(\"No\") }}</td>\n					<td class=\"text-left\">{{ _(\"Item\") }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ _(\"Item Code\") }}</td>\n					{% endif %}\n					<td class=\"text-right\">{{ _(\"Quantity\") }}</td>\n					<td class=\"text-right\">{{ _(\"Rate\") }}</td>\n					<td class=\"text-right\">{{ _(\"Amount\") }}</td>\n				</tr>\n			</thead>\n			<tbody>\n				{% for item in doc.items %}\n				<tr>\n					<td class=\"text-center text-dark\">{{ loop.index }}</td>\n					<td>{{ item.item_name }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ item.item_code }}</td>\n					{% endif %}\n					<td class=\"text-right text-dark\">{{ item.get_formatted(\"qty\", 0) }} {{ item.uom }}</td>\n					<td class=\"text-right text-dark\">{{ item.get_formatted(\"net_rate\", doc) }}</td>\n					<td class=\"text-right\" style=\"color: #171717\">\n						{{ item.get_formatted(\"net_amount\", doc) }}\n					</td>\n				</tr>\n				{% endfor %}\n			</tbody>\n		</table>\n\n		<!-- Totals Section -->\n		<table style=\"width:100%; margin-top: 15px\">\n			<td style=\"vertical-align: bottom !important; width: 60%;\">\n				<p class=\"title\">{{ _(\"Total in words\") }}</p>\n				<div class=\"words-box text-uppercase\">{{ doc.in_words }}</div>\n			</td>\n			<td>\n				&nbsp;\n			</td>\n			<td style=\"width: 38%;\">\n				<table class=\"totals-table\">\n					<tr>\n						<td class=\"text-right text-muted\"><div></div>{{ _(\"Sub Total:\") }}</td>\n						<td class=\"text-right amount-width\">{{ doc.get_formatted(\"total\", doc) }}</td>\n					</tr>\n					{%- if doc.apply_discount_on == \"Net Total\" -%}\n						<tr>\n							<td class=\"text-right text-muted\">\n								<div></div>{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n							</td>\n							<td class=\"text-right amount-width\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n						</tr>\n					{%- endif -%}\n					{%- for tax in doc.taxes -%}\n						{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}\n							<tr>\n								<td class=\"text-right text-muted\"><div></div>{{ tax.get_formatted(\"description\") }} ({{ tax.get_formatted(\"rate\") }}%):</td>\n								<td class=\"text-right amount-width\">{{ tax.get_formatted(\"tax_amount\") }}</td>\n							</tr>\n						{%- endif -%}\n					{%- endfor -%}\n					{%- if doc.apply_discount_on == \"Grand Total\" -%}\n						<tr>\n							<td class=\"text-right text-muted\">\n								<div></div>{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n							</td>\n							<td class=\"text-right amount-width\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n						</tr>\n					{%- endif -%}\n					<tr class=\"grand-total\">\n						<td class=\"text-right\">{{ _(\"Grand Total:\") }}</td>\n						<td class=\"text-right amount-width\">{{ doc.get_formatted(\"grand_total\", doc) }}</td>\n					</tr>\n				</table>\n			</td>\n		</table>\n\n		<!-- Terms -->\n		<div class=\"terms-section\">\n			{% if doc.terms %}\n			<div class=\"info-card mt-40\">\n				<div>{{ _(\"Terms and Conditions\") }}</div>\n				{{ doc.terms}}\n			</div>\n			{% endif %}\n		</div>\n	</div>\n	<div {% if print_settings.repeat_header_footer %} id=\"footer-html\" class=\"visible-pdf\" {% endif %}>\n		{% if not no_letterhead and footer %}\n		<div class=\"letter-head-footer\">\n			{{ footer }}\n		</div>\n		{% endif %}\n		{% if print_settings.repeat_header_footer %}\n		<p class=\"text-center small page-number visible-pdf\">\n			{{ _(\"Page {0} of {1}\").format(\'<span class=\"page\"></span>\', \'<span class=\"topage\"></span>\') }}\n		</p>\n		{% endif %}\n	</div>\n</div>\n{% endfor %}',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('Quotation with Item Image','2026-03-18 11:57:39.954918','2026-07-03 02:26:31.243291','Administrator','Administrator',0,0,'DocType','Quotation',NULL,'Selling','en','Yes',1,0,'wkhtmltopdf','Jinja',0,'{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}\n\n{% if letter_head and not no_letterhead %}\n<div class=\"letter-head\">{{ letter_head }}</div>\n{% endif %}\n{% if print_heading_template %}\n{{ frappe.render_template(print_heading_template, {\"doc\":doc}) }}\n{% endif %}\n{%- endmacro -%}\n\n{% for page in layout %}\n<div class=\"page-break invoice-page\">\n	<div {% if print_settings.repeat_header_footer %} id=\"header-html\" class=\"hidden-pdf\" {% endif %}>\n		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}\n	</div>\n	{%- if doc.meta.is_submittable and doc.docstatus==2-%}\n		<div class=\"text-center\" document-status=\"cancelled\">\n			<h4 style=\"margin-top: 20px;\">{{ _(\"CANCELLED\") }}</h4>\n		</div>\n	{%- endif -%}\n	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}\n		<div class=\"text-center\" document-status=\"draft\">\n			<h4 style=\"margin-top: 20px !important;\">{{ _(\"DRAFT\") }}</h4>\n		</div>\n	{%- endif -%}\n\n	<style>\n		.letter-head {\n			padding-top: 12px !important;\n			padding-bottom: 12px !important;\n		}\n		.invoice-page {\n			font-family: Inter, sans-serif;\n			color: #171717;\n		}\n\n		.print-format-body {\n			padding: 30px 12px 12px 12px !important;\n		}\n\n		.title {\n			color: #7c7c7c !important;\n		}\n		.text-muted {\n			color: #7c7c7c !important;\n		}\n		.text-dark {\n			color: #171717 !important;\n		}\n		.small-text {\n			font-size: 11px;\n			color: #666;\n		}\n\n		.text-left {\n			text-align: left;\n		}\n		.text-center {\n			text-align: center;\n		}\n		.text-right {\n			text-align: right;\n		}\n		.text-bold {\n			font-weight: 700;\n		}\n\n		.mt-15 {\n			margin-top: 15px;\n		}\n		.mt-16 {\n			margin-top: 16px;\n		}\n		.mt-40 {\n			margin-top: 40px;\n		}\n		.mw-400 {\n			max-width: 400px;\n		}\n\n		.items-table,\n		.tax-table {\n			width: 100%;\n			border-collapse: separate;\n			border-spacing: 0;\n			border-radius: 10px;\n			overflow: hidden;\n		}\n\n		.items-table td,\n		.tax-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px;\n		}\n\n		.items-table thead td,\n		.tax-table thead td {\n			color: #7c7c7c !important;\n		}\n		.items-table thead tr:first-of-type td,\n		.tax-table thead tr:first-of-type td {\n			border-bottom: none;\n		}\n\n		.items-table thead tr:first-child td:first-child,\n		.tax-table thead tr:first-child td:first-child {\n			border-top-left-radius: 10px;\n			border-bottom-left-radius: 10px;\n		}\n		.items-table thead tr:first-child td:last-child,\n		.tax-table thead tr:first-child td:last-child {\n			border-top-right-radius: 10px;\n			border-bottom-right-radius: 10px;\n		}\n\n		.in-words {\n			color: #171717 !important;\n			max-width: 400px;\n			word-wrap: break-word;\n			line-height: 1.5;\n			font-size: 12px;\n		}\n\n		.row-divider {\n			border-bottom: 1px solid #e9e9e9;\n		}\n\n		.highlight-bg {\n			background: #f8f8f8;\n		}\n\n		.info-card {\n			margin-top: 40px;\n			color: #7c7c7c;\n		}\n\n		.info-text {\n			margin-bottom: 12px;\n		}\n\n		.print-format {\n			color: #171717;\n			font-size: 14px;\n			font-style: normal;\n			font-weight: 420;\n			line-height: 21px;\n			padding: 0px !important;\n			margin-left: 0mm !important;\n			margin-right: 0mm !important;\n		}\n\n		.letter-head-footer {\n			margin-top: 0px !important;\n		}\n\n		.print-format-body td {\n			padding: 8px 8px !important;\n		}\n\n		.tax-table td,\n		.items-table td {\n			height: auto !important;\n		}\n\n		.tax-table thead td,\n		.items-table thead td {\n			height: 32px;\n		}\n\n		.item-img td {\n			border: none !important;\n			padding: 0px !important;\n		}\n	</style>\n\n	<div class=\"print-format-body\">\n		<table class=\"info-table col-xs-12\" style=\"width: 100%; margin-left: 12px\">\n			<tr>\n				<td class=\"col-xs-6\" style=\"padding: 0 !important\">\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">Customer Name:</div>\n						<div class=\"info-text\">Bill to:</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ doc.customer_name }}</div>\n						<div class=\"info-text\">\n        					{% if doc.customer_address %}\n        						{% set customer_address = frappe.db.get_value(\"Address\", doc.customer_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %}\n        						{{ customer_address.address_line1 or \"\" }}<br>\n        						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}\n        						{{ customer_address.city or \"\" }} {{ customer_address.state or \"\" }} {{ customer_address.pincode or \"\" }} {{ customer_address.country or \"\" }}<br>\n        					{% endif %}\n						</div>\n\n					</div>\n				</td>\n\n				<td class=\"col-xs-6\" style=\"padding: 0 !important\">\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Quotation:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ doc.name }}</div>\n					</div>\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Posting Date:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ frappe.utils.format_date(doc.transaction_date) }}</div>\n					</div>\n					<div class=\"title col-xs-5 p-0\">\n						<div class=\"info-text\">{{ _(\"Valid Till:\") }}</div>\n					</div>\n					<div class=\"col-xs-7\">\n						<div class=\"info-text\">{{ frappe.utils.format_date(doc.valid_till) }}</div>\n					</div>\n				</td>\n			</tr>\n		</table>\n\n		<!-- Items Table -->\n		{% set item_naming_by = frappe.db.get_single_value(\"Stock Settings\", \"item_naming_by\") %}\n		<table class=\"items-table mt-15\">\n			<thead class=\"highlight-bg\">\n				<tr>\n					<td class=\"	text-center\">{{ _(\"No\") }}</td>\n					<td class=\"text-left\">{{ _(\"Item\") }}</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ _(\"Item Code\") }}</td>\n					{% endif %}\n					<td class=\"text-right\">{{ _(\"Quantity\") }}</td>\n					<td class=\"text-right\">{{ _(\"Rate\") }}</td>\n					<td class=\"text-right\">{{ _(\"Amount\") }}</td>\n				</tr>\n			</thead>\n			<tbody>\n				{% for item in doc.items %}\n				<tr>\n					<td class=\"text-center\">{{ loop.index }}</td>\n					<td class=\"text-left\">\n						<table class=\"item-img\" style=\"border-collapse: collapse\">\n							<tr>\n								{% if item.image %}\n								<td class=\"no-style\" style=\"border-radius: 6px; vertical-align: middle\">\n									<img\n										src=\"{{ item.image }}\"\n										alt=\"{{ item.item_name }}\"\n										style=\"\n											border-radius: 6px;\n											height: 24px;\n											width: 24px !important;\n											margin-right: 8px;\n                                            vertical-align: middle;\n										\"\n									/>\n								</td>\n								{% endif %}\n								<td\n									class=\"no-style\"\n									style=\"vertical-align: middle !important; padding: 0 !important\"\n								>\n									{{ item.item_name }}\n								</td>\n							</tr>\n						</table>\n					</td>\n					{% if item_naming_by != \"Item Code\" %}\n						<td class=\"text-left\">{{ item.item_code }}</td>\n					{% endif %}\n\n					<td class=\"text-right\">{{ item.get_formatted(\"qty\", 0) }} {{ item.uom }}</td>\n					<td class=\"text-right\">{{ item.get_formatted(\"net_rate\", doc) }}</td>\n					<td class=\"text-right\">{{ item.get_formatted(\"net_amount\", doc) }}</td>\n				</tr>\n				{% endfor %}\n			</tbody>\n		</table>\n\n		<div class=\"test\" style=\"float: right; margin-top: 15px; margin-bottom: 5px;\">\n			<table style=\"width: 100%; border-collapse: collapse\">\n				<tr class=\"row-divider\">\n					<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">{{ _(\"Sub Total:\") }}</td>\n					<td class=\"text-right\">{{ doc.get_formatted(\"total\", doc) }}</td>\n				</tr>\n\n				{%- if doc.apply_discount_on == \"Net Total\" -%}\n					<tr class=\"row-divider\">\n						<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">\n							{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n						</td>\n						<td class=\"text-right\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n					</tr>\n				{%- endif -%}\n				{%- for tax in doc.taxes -%}\n					{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}\n						<tr class=\"row-divider\">\n							<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">{{ tax.get_formatted(\"description\") }} ({{ tax.get_formatted(\"rate\") }}%):</td>\n							<td class=\"text-right\">{{ tax.get_formatted(\"tax_amount\") }}</td>\n						</tr>\n					{%- endif -%}\n				{%- endfor -%}\n				{%- if doc.apply_discount_on == \"Grand Total\" -%}\n					<tr class=\"row-divider\">\n						<td class=\"text-right text-muted\" style=\"padding-right: 30px !important;\">\n							{{ _(\"Discount\") }} ({{ doc.additional_discount_percentage }}%):\n						</td>\n						<td class=\"text-right\">{{ doc.get_formatted(\"discount_amount\", doc) }}</td>\n					</tr>\n				{%- endif -%}\n			</table>\n		</div>\n\n		<div style=\"border-bottom: 1px solid #ededed;\">\n			<table class=\"highlight-bg\" style=\"width: 100%; border-collapse: collapse; border-radius: 12px; margin-bottom: 10px;\">\n				<tr>\n					<td class=\"text-left mw-400\">\n						<div class=\"text-capitalize\">\n							<span class=\"title\"> {{ _(\"In Words: \") }}</span>{{ doc.in_words }}\n						</div>\n					</td>\n					<td class=\"text-right\"><b>{{ _(\"Grand Total:\") }}</b></td>\n					<td class=\"text-right\">\n						<span style=\"font-weight: 700\">\n							{{ doc.get_formatted(\"grand_total\", doc) }}\n						</span>\n					</td>\n				</tr>\n			</table>\n		</div>\n\n\n		<!-- Terms -->\n		{% if doc.terms %}\n		<div class=\"info-card\">\n			<div class=\"title\">{{ _(\"Terms and Conditions\") }}</div>\n			{{ doc.terms}}\n		</div>\n		{% endif %}\n	</div>\n	<div {% if print_settings.repeat_header_footer %} id=\"footer-html\" class=\"visible-pdf\" {% endif %}>\n		{% if not no_letterhead and footer %}\n		<div class=\"letter-head-footer\">\n			{{ footer }}\n		</div>\n		{% endif %}\n		{% if print_settings.repeat_header_footer %}\n		<p class=\"text-center small page-number visible-pdf\">\n			{{ _(\"Page {0} of {1}\").format(\'<span class=\"page\"></span>\', \'<span class=\"topage\"></span>\') }}\n		</p>\n		{% endif %}\n	</div>\n</div>\n{% endfor %}',NULL,15.000000000,15.000000000,15.000000000,15.000000000,0,0,0,0,14,NULL,'Hide',NULL,NULL,0,0,NULL,NULL,NULL,NULL),
