le.items-table td,\n		table.tax-table td {\n			border-bottom: 1px solid #ededed;\n			padding: 8px;\n		}\n\n		table.info-table td:not(:first-of-type),\n		table.items-table td:not(:first-of-type),\n		table.tax-table td:not(:first-of-type) {\n			border-left: 1px solid #ededed;\n		}\n\n		table.info-table tbody tr:last-of-type td,\n		table.items-table tbody tr:last-of-type td,\n		table.tax-table tbody tr:last-of-type td {\n			border-bottom: none;\n		}\n\n		thead.table-header {\n			background: #f8f8f8;\n		}\n		thead.table-header td {\n			color: #7c7c7c;\n		}\n\n		.text-center {\n			text-align: center;\n		}\n		.text-left {\n			text-align: left;\n		}\n		.text-right {\n			text-align: right;\n		}\n		.text-muted {\n			color: #7c7c7c;\n		}\n		.text-dark {\n			color: #525252;\n		}\n		.text-bold {\n			font-weight: bold;\n		}\n		.small-text {\n			color: #666;\n		}\n\n		.mt-10 {\n			margin-top: 10px;\n		}\n		.mt-15 {\n			margin-top: 15px;\n		}\n		.mt-20 {\n			margin-top: 20px;\n		}\n		.mt-40 {\n			margin-top: 40px;\n		}\n		.mt-80 {\n			margin-top: 80px;\n		}\n		.mb-20 {\n			margin-bottom: 20px;\n		}\n		.pb-8 {\n			padding-bottom: 8px;\n		}\n		.amount-width {\n			width: 110px;\n		}\n\n		.totals-table {\n			border-radius: 5px;\n			width: 100%;\n		}\n		.totals-table td {\n			padding: 4px 8px;\n		}\n		.totals-table tr {\n			border-bottom: 1px solid #ededed;\n			position: relative;\n		}\n		.totals-table tr td {\n			position: relative;\n		}\n		.totals-table tr td div {\n			width: 12%;\n			height: 14px;\n			background-color: white;\n			position: absolute;\n			bottom: -6px;\n			left: 0%;\n			color: white;\n		}\n		.totals-table tr:last-child {\n			border-bottom: none;\n		}\n		.totals-table .grand-total td {\n			padding: 6px 8px;\n			font-weight: bold;\n		}\n\n		.words-box {\n			background: #f8f8f8;\n			border-radius: 8px;\n			padding: 8px;\n			line-height: 21px;\n			letter-spacing: 0.21px;\n			font-size: small;\n		}\n\n		.info-card {\n			color: #7c7c7c;\n		}\n\n		.title {\n			color: #7c7c7c